-- First Not Smaller (Easy)
INSERT INTO coding_problems (slug, title, description, difficulty, category, type, tags, starter_code, test_cases, examples, constraints, points, order_index, time_limit_ms, memory_limit_kb, input_format, output_format, editorial, judged)
VALUES ($q$first-not-smaller$q$, $q$First Not Smaller$q$, $q$You are given an array sorted in non-decreasing order and q queries. For each query value x, print the smallest index i with a[i] ≥ x. If every element is smaller than x, print n.$q$, $q$Easy$q$, $q$Binary Search$q$, 'code', ARRAY[$q$binary-search$q$, $q$array$q$]::text[], $q${"python": "import sys\n\n\ndef main():\n    lines = sys.stdin.read().split('\\n')\n    # Input:\n    # Line 1: n and q.\n    # Line 2: n integers in non-decreasing order.\n    # Line 3: q integers, the queries.\n    # TODO: solve, then print the answer\n\n\nmain()\n", "javascript": "const lines = require('fs').readFileSync(0, 'utf8').split('\\n');\n// Input:\n// Line 1: n and q.\n// Line 2: n integers in non-decreasing order.\n// Line 3: q integers, the queries.\n// TODO: solve, then console.log the answer\n", "java": "import java.io.*;\nimport java.util.*;\n\npublic class Main {\n    public static void main(String[] args) throws IOException {\n        BufferedReader in = new BufferedReader(new InputStreamReader(System.in));\n        List<String> lines = new ArrayList<>();\n        for (String s; (s = in.readLine()) != null; ) lines.add(s);\n        // Input:\n        // Line 1: n and q.\n        // Line 2: n integers in non-decreasing order.\n        // Line 3: q integers, the queries.\n        // TODO: solve, then System.out.println the answer\n    }\n}\n", "cpp": "#include <bits/stdc++.h>\nusing namespace std;\n\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    // Input:\n    // Line 1: n and q.\n    // Line 2: n integers in non-decreasing order.\n    // Line 3: q integers, the queries.\n    // TODO: read with cin / getline, solve, print the answer\n    return 0;\n}\n", "c": "#include <stdio.h>\n\nint main(void) {\n    // Input:\n    // Line 1: n and q.\n    // Line 2: n integers in non-decreasing order.\n    // Line 3: q integers, the queries.\n    /* TODO: read with scanf / fgets, solve, print the answer */\n    return 0;\n}\n"}$q$::jsonb, '[]'::jsonb, $q$[{"input": "5 4\n1 3 3 5 8\n0 3 4 9", "output": "0\n1\n3\n5", "explanation": "3 first appears at index 1; nothing is ≥ 9, so the answer is n = 5."}, {"input": "1 2\n7\n7 8", "output": "0\n1", "explanation": ""}]$q$::jsonb, ARRAY[$q$1 ≤ n, q ≤ 10 000$q$, $q$-10^6 ≤ a[i], x ≤ 10^6$q$]::text[], 10, 1005, 2000, 262144, $q$Line 1: n and q.
Line 2: n integers in non-decreasing order.
Line 3: q integers, the queries.$q$, $q$q lines. Line k holds the answer to query k.$q$, $q$Binary search on the answer. Keep lo = 0, hi = n. While lo < hi take mid; if a[mid] < x the answer is to the right (lo = mid + 1), otherwise hi = mid. O(log n) per query. Scanning from the left is O(n) per query and too slow at the upper limits.$q$, false)
ON CONFLICT (slug) DO NOTHING;

